require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');$sid=student_id($pdo);$s=$pdo->prepare('SELECT a.application_date,a.status,i.title,c.company_name,v.interview_date,v.interview_time,v.mode,v.result,v.remarks FROM application a JOIN internship i ON i.internship_id=a.internship_id JOIN company c ON c.company_id=i.company_id LEFT JOIN interview v ON v.application_id=a.application_id WHERE a.student_id=? ORDER BY a.application_date DESC');$s->execute([$sid]);$rows=$s->fetchAll();$b='<h2>My applications</h2>'.(!empty($_GET['applied'])?'<p class="ok">Application submitted.</p>':'');
foreach($rows as $r)$b.='<section class="card"><h3>'.e($r['title']).'</h3><p>'.e($r['company_name']).' · Applied '.e($r['application_date']).' · Status: <b>'.e($r['status']).'</b></p>'.($r['interview_date']?'<p>Interview: '.e($r['interview_date']).' '.e($r['interview_time']).' · '.e($r['mode']).' · '.e($r['result']).' '.e($r['remarks']).'</p>':'').'</section>';if(!$rows)$b.='<p>No applications yet.</p>';page('Applications',$b);
